import schoolLogoAsset from '../assets/logo-lqd.png';

/**
 * Standardized school crest assets for Trường THPT Chuyên Lê Quý Đôn – Vũng Tàu.
 * 1. Primary: Vite-bundled static import from src/assets/logo-lqd.png
 * 2. Secondary: Public lowercase static path /images/logo-lqd.png
 * 3. Tertiary: Embedded inline Data URI fallback (zero network dependency on Vercel/offline)
 */
export const SCHOOL_LOGO_PRIMARY_SRC: string = schoolLogoAsset;
export const SCHOOL_LOGO_PUBLIC_FALLBACK_SRC = '/images/logo-lqd.png';
export const SCHOOL_LOGO_INLINE_DATA_URI = 'data:image/png;base64,';

export const SCHOOL_LOGO_FALLBACK_CHAIN: readonly string[] = [
  SCHOOL_LOGO_PRIMARY_SRC,
  SCHOOL_LOGO_PUBLIC_FALLBACK_SRC,
  SCHOOL_LOGO_INLINE_DATA_URI,
];
